// Review-only harness. Compile unchanged Core + UsageStore directly in this module.
// Inputs must be generated by generate-scale.py. This program never mutates them.
// Session projections measure underlying synchronous computation, not SwiftUI frames.
import Foundation

private func timed<T>(_ operation: () throws -> T) rethrows -> (T, Double) {
    let start = ProcessInfo.processInfo.systemUptime
    let value = try operation()
    return (value, ProcessInfo.processInfo.systemUptime - start)
}

private func emit(_ result: [String: Any]) throws {
    let data = try JSONSerialization.data(withJSONObject: result, options: [.sortedKeys])
    print(String(decoding: data, as: UTF8.self))
    fflush(stdout)
}

private func stats(_ values: [Double]) -> [String: Any] {
    let sorted = values.sorted()
    return ["samplesSeconds": values, "medianSeconds": sorted[sorted.count / 2], "minSeconds": sorted[0]]
}

@main private struct ScaleProbe {
    @MainActor static func main() throws {
        precondition((2...3).contains(CommandLine.arguments.count), "Usage: scale-probe GENERATED_ROOT [--skip-projections]")
        let skipProjections = CommandLine.arguments.count == 3
        if skipProjections { precondition(CommandLine.arguments[2] == "--skip-projections") }
        let root = URL(fileURLWithPath: CommandLine.arguments[1])
        let manifest = try JSONSerialization.jsonObject(with: Data(contentsOf: root.appendingPathComponent("manifest.json"))) as! [String: Any]
        precondition(manifest["synthetic"] as? String == "codex-stats-review-scale-v1", "Only review-generated fixtures are accepted")
        try emit(["kind": "environment", "system": ProcessInfo.processInfo.operatingSystemVersionString,
                  "timeZone": TimeZone.current.identifier, "processorCount": ProcessInfo.processInfo.processorCount,
                  "note": "release underlying computation; no UI frame or current footprint measurement"])
        for item in manifest["cases"] as! [[String: Any]] {
            try autoreleasepool {
                let count = item["turns"] as! Int
                precondition((1...5000).contains(count))
                let directory = item["directory"] as! String
                let completed = item["completeTurns"] as? Bool ?? true
                precondition(directory == "\(completed ? "turns" : "requests")-\(count)")
                try turnCase(root.appendingPathComponent(directory), count: count, bytes: item["bytes"] as! Int, completed: completed)
            }
        }
        if !skipProjections {
            for count in [1000, 5000] {
                try autoreleasepool { try projectionCase(count: count) }
            }
        }
    }

    static func turnCase(_ root: URL, count: Int, bytes: Int, completed: Bool) throws {
        let scanner = CodexLogScanner(timeZone: TimeZone(secondsFromGMT: 0)!)
        let (first, cold) = try timed { try scanner.scan(homePath: root.path) }
        let expected = TokenUsage(input: Int64(count) * 100, cachedInput: Int64(count) * 80,
                                  output: Int64(count) * 20, reasoning: Int64(count) * 10)
        func check(_ report: ScanReport) -> [UsageRecord] {
            let rows = report.records(in: .all, sortedByTime: false)
            precondition(report.fileCount == 1 && report.sessions.count == 1 && report.diagnostics.isEmpty)
            precondition(rows.count == count && report.totals(in: .all) == expected)
            precondition(rows.reduce(TokenUsage()) { $0 + $1.usage } == expected)
            precondition(Set(rows.compactMap(\.requestID)).count == count)
            precondition(rows.allSatisfy { row in
                guard row.evidence == .responseRecord else { return false }
                guard completed else { return row.turnPerformance == nil }
                return row.turnPerformance?.durationMilliseconds == 2000 &&
                row.turnPerformance?.firstTokenMilliseconds == 100 && row.turnPerformance?.outputTokens == 20 &&
                row.turnPerformance?.responseCount == 1 && row.turnPerformance?.averageOutputTokensPerSecond == 10
            })
            return rows
        }
        let firstRows = check(first)
        var warm: [Double] = []
        for _ in 0..<3 {
            let (report, elapsed) = try timed { try scanner.scan(homePath: root.path) }
            precondition(report.cachedFileCount == 1 && check(report) == firstRows)
            warm.append(elapsed)
        }
        try emit(["kind": completed ? "completeTurns" : "withoutCompletion", "turns": count, "bytes": bytes,
                  "coldSeconds": cold, "warm": stats(warm), "total": expected.total,
                  "invariants": "all tokens, identities, timing and unchanged rows passed"])
    }

    private struct SessionRow {
        let session: SessionUsage
        let usage: TokenUsage
        let models: [ModelUsage]
        var id: String { session.id }
    }

    // Mirrors SessionsContent.matching(now:) for default empty search + recent sort.
    // This uses the actual Core methods; no implementation optimization is substituted.
    private static func sessionProjection(_ report: ScanReport, period: UsagePeriod, now: Date) -> [SessionRow] {
        let search = ""
        let rows = report.recentSessions(in: period, now: now).compactMap { session -> SessionRow? in
            let usage = session.usage(in: period, now: now)
            let models = session.modelUsage(in: period, now: now)
            guard search.isEmpty || session.title.localizedCaseInsensitiveContains(search)
                || session.project.localizedCaseInsensitiveContains(search)
                || (session.recordedSessionID?.localizedCaseInsensitiveContains(search) ?? false)
                || models.contains(where: { $0.model.localizedCaseInsensitiveContains(search) }) else { return nil }
            return SessionRow(session: session, usage: usage, models: models)
        }
        return rows.sorted {
            $0.session.lastActivity == $1.session.lastActivity ? $0.id < $1.id : $0.session.lastActivity > $1.session.lastActivity
        }
    }

    @MainActor static func projectionCase(count: Int) throws {
        let now = Date(timeIntervalSince1970: 1_792_065_600) // Stable date; its local day is used throughout.
        let day = UsagePeriod.dateString(now)
        let hour = Calendar.current.dateInterval(of: .hour, for: now)!.start
        let usage = TokenUsage(input: 100, cachedInput: 80, output: 20, reasoning: 10)
        let sessions: [SessionUsage] = (0..<count).map { index in
            let id = "synthetic-session-\(index)"
            let record = UsageRecord(id: "row-\(index)", sessionID: id, recordedSessionID: id,
                project: "synthetic-project", source: "synthetic", fileName: "synthetic.jsonl",
                timestamp: now, day: day, model: "synthetic-model", requestID: "request-\(index)",
                turnID: nil, usage: usage, evidence: .responseRecord, isCompaction: false,
                cumulativeSnapshot: nil, lastReportedUsage: usage)
            return SessionUsage(id: id, project: "synthetic-project", title: id,
                workingDirectory: "/synthetic", source: "synthetic", isFork: false,
                replayDeduplicated: false, replayUnverified: false, firstActivity: now, lastActivity: now,
                dailyModel: [DailyModelUsage(day: day, model: "synthetic-model", usage: usage)],
                fileName: "synthetic.jsonl", hourlyUsage: [hour: usage], records: [record], recordedSessionID: id)
        }
        let report = ScanReport(sessions: sessions, fileCount: count, invalidLineCount: 0,
                                diagnostics: [], refreshedAt: now)
        let total = Int64(count) * 120
        for period in [UsagePeriod.today, .all] {
            var summaryTimes: [Double] = [], projectionTimes: [Double] = [], requestTimes: [Double] = []
            for _ in 0..<5 {
                let (summary, summaryTime) = timed { UsageSummary(report: report, period: period, now: now) }
                precondition(summary.usage.total == total && summary.models.count == 1 && summary.models[0].sessionCount == count)
                precondition(summary.dailyTotals.reduce(Int64(0)) { $0 + $1.usage.total } == total)
                precondition(period != .today || summary.hourlyTotals.reduce(Int64(0)) { $0 + $1.usage.total } == total)
                summaryTimes.append(summaryTime)
                let (projection, projectionTime) = timed { sessionProjection(report, period: period, now: now) }
                precondition(projection.count == count && projection.reduce(Int64(0)) { $0 + $1.usage.total } == total)
                precondition(projection.allSatisfy { $0.models.count == 1 && $0.models[0].usage == usage })
                projectionTimes.append(projectionTime)
                let (records, requestTime) = timed { report.records(in: period, now: now) }
                precondition(records.count == count && records.reduce(Int64(0)) { $0 + $1.usage.total } == total)
                requestTimes.append(requestTime)
            }
            try emit(["kind": "sessionProjections", "sessions": count, "period": period.rawValue,
                      "summaryColdComputation": stats(summaryTimes), "sessionProjection": stats(projectionTimes),
                      "coreRequestFilterSort": stats(requestTimes), "total": total,
                      "invariants": "session, model, daily, hourly, summary and record totals passed",
                      "scope": "synchronous underlying computation on MainActor; no UI/frame claim; each summary is cache miss"])
        }
    }
}
